                  Norm1 --> Attn["GQA + RoPE Attention"]
                  Attn --> Add1["Residual Connection (Сложение)"]
                  
                  Add1 --> Norm2["RMSNorm"]
                  Norm2 --> FFN["Sparse MoE / SwiGLU FFN"]
